import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Testing-for-differences-of-means.md","filePath":"manual-zh/Testing-for-differences-of-means.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Testing-for-differences-of-means.md"};function n(s,t,h,p,i,l){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-3-1-均值差异检验" tabindex="-1">5.3.1 均值差异检验 <a class="header-anchor" href="#_5-3-1-均值差异检验" aria-label="Permalink to &quot;5.3.1 均值差异检验&quot;">​</a></h4><p>一种常见的统计检验涉及关于均值的假设。<code>T-TEST</code> 命令用于判断两个独立的子集是否具有相同的均值。</p><p>一位研究者怀疑人的身高与核心体温可能因其性别不同而存在差异。为进行研究，他基于先前遇到的 physiology.sav 数据提出了两个原假设：</p><ul><li>总体中男性与女性的平均身高相等。</li><li>总体中男性与女性的平均体温相等。</li></ul><p>出于研究目的，研究者决定使用 0.05 的 p 值。</p><p>除 T 检验外，<code>T-TEST</code> 命令还会执行方差齐性的 Levene 检验。若方差相等，则可使用功效更高的 T 检验形式。但如果假定方差相等并不稳妥，则需要另一种计算方式。PSPP 会同时执行两种计算。</p><p>对于 <strong>height</strong> 变量，输出显示 Levene 检验的显著性为 0.33，这意味着当方差相等时，Levene 检验产生此结果的概率为 33%。若显著性小于 0.05，则假定方差相等就不稳妥了。然而，由于该值高于 0.05，方差齐性假设是安全的，可以使用“假定方差相等”行（即功效更高的检验）。查看该行，<strong>height</strong> 的 t 检验双尾显著性小于 0.05，因此可以安全地拒绝原假设，并得出男性与女性平均身高不相等的结论。</p><p>对于 <strong>temperature</strong> 变量，Levene 检验的显著性为 0.58，因此同样可以使用方差相等行。方差相等行显示 <strong>temperature</strong> 的双尾显著性为 0.20。由于该值大于 0.05，我们必须拒绝原假设，并得出证据不足以表明男性与女性的体温存在差异的结论。</p><p>本分析的语法为：</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/physiology.sav&#39;.
PSPP&gt; recode height (179 = SYSMIS).
PSPP&gt; t-test group=sex(0,1) /variables = height temperature.
</code></pre><p>PSPP 为该语法产生如下输出：</p><table tabindex="0"><thead><tr><th></th><th></th><th>F</th><th>显著性</th><th>t</th><th>df</th><th>显著性（双尾）</th><th>均值差</th><th>均值差标准误</th><th>差值 95% 置信区间</th><th></th></tr></thead><tbody><tr><td></td><td>组</td><td>N</td><td>均值</td><td>标准差</td><td>均值标准误</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>身高（毫米）</td><td>男性</td><td>22</td><td>1796.49</td><td>49.71</td><td>10.60</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>女性</td><td>17</td><td>1610.77</td><td>25.43</td><td>6.17</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>体内温度（摄氏度）</td><td>男性</td><td>22</td><td>36.68</td><td>1.95</td><td>.42</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>女性</td><td>18</td><td>37.43</td><td>1.61</td><td>.38</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>方差齐性 Levene 检验</td><td>均值相等性 T 检验</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>下限</td><td>上限</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>身高（毫米）</td><td>假定方差相等</td><td>.97</td><td>.331</td><td>14.02</td><td>37.00</td><td>.000</td><td>185.72</td><td>13.24</td><td>158.88</td><td>212.55</td></tr><tr><td>不假定方差相等</td><td></td><td></td><td>15.15</td><td>32.71</td><td>.000</td><td>185.72</td><td>12.26</td><td>160.76</td><td>210.67</td><td></td></tr><tr><td>体内温度（摄氏度）</td><td>假定方差相等</td><td>.31</td><td>.581</td><td>-1.31</td><td>38.00</td><td>.198</td><td>-.75</td><td>.57</td><td>-1.91</td><td>.41</td></tr><tr><td>不假定方差相等</td><td></td><td></td><td>-1.33</td><td>37.99</td><td>.190</td><td>-.75</td><td>.56</td><td>-1.89</td><td>.39</td><td></td></tr></tbody></table><p><code>T-TEST</code> 命令检验均值的差异。此处 <strong>height</strong> 变量的双尾显著性小于 0.05，因此可以拒绝原假设。于是，证据表明男性与女性的身高存在差异。而 <strong>temperature</strong> 变量的检验显著性大于 0.05，因此无法拒绝原假设，证据不足以表明体温存在差异。</p>`,13)])])}const f=d(o,[["render",n]]);export{g as __pageData,f as default};
